;
const DOCS=CONTENT.documents, byId=Object.fromEntries(DOCS.map(d=>[d.id,d]));
const INITIAL=CONTENT.initialIds;
const AREAS=[{id:'med',title:'Dokumentacja medyczna',desc:'Oględziny i materiały sądowo-medyczne'},{id:'tech',title:'Warsztat i tabor',desc:'Karty serwisowe, diagnostyka, przeglądy'},{id:'digital',title:'Archiwum cyfrowe',desc:'Rejestry, logi, korespondencja'},{id:'cctv',title:'Monitoring zajezdni',desc:'Nagrania i dokumentacja wizualna'},{id:'admin',title:'Dyspozytornia i akta',desc:'Obsada, procedury, oświadczenia'},{id:'lab',title:'Zabezpieczone próbki',desc:'Mikroślady i dokumentacja porównawcza'}];
const STATE={found:new Set(INITIAL),reviewedEvidence:new Set(),notes:'',events:[],dialogues:{},activeChar:CONTENT.characters[0].id,area:'admin',tab:'overview'};
for(const c of CONTENT.characters){STATE.dialogues[c.id]=[{role:'npc',text:c.voice.opening}];}
const $=id=>document.getElementById(id);
function psCount(n,one,few,many){const v=Math.abs(Number(n)||0),last=v%10,last2=v%100;return v+' '+(v===1?one:(last>=2&&last<=4&&(last2<12||last2>14)?few:many));}
function esc(s){return String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function norm(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ł/g,'l').replace(/[^a-z0-9 ]+/g,' ').replace(/\s+/g,' ').trim();}
const STOP=new Set('i a o u z ze na do od po za dla co kto jak czy jest sa byl byla gdzie kiedy teraz sie jego jej pan pani moje moja swoja tym ten ta te oraz przez przy gdy ktory jakie jaki wie jest zostal'.split(' '));
function tokens(s){return norm(s).split(' ').filter(t=>t.length>=4&&!STOP.has(t)).map(t=>t.slice(0,Math.min(6,t.length)));}
let toastTimer;
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
// Single navigation owner: historical modules register lifecycle hooks, never replace showTab.
const PS_NAV_TABS=Object.freeze(['overview','evidence','search','interview','timeline','inspection12','notebook','labs','deduction','final']);
const PS_NAV_HOOKS=[];
function registerNavigationHook(spec){
 if(!spec || typeof spec.name!=='string' || !spec.name.trim() ||
   (typeof spec.before!=='function' && typeof spec.after!=='function'))throw Error('Nieprawidłowy hook nawigacji');
 if(PS_NAV_HOOKS.some(h=>h.name===spec.name))throw Error('Powtórzony hook nawigacji: '+spec.name);
 const hook=Object.freeze({name:spec.name,before:spec.before,after:spec.after});
 PS_NAV_HOOKS.push(hook);
 return ()=>{const index=PS_NAV_HOOKS.indexOf(hook);if(index>=0)PS_NAV_HOOKS.splice(index,1);};
}
function showTab(id){
 if(!PS_NAV_TABS.includes(id) || !document.getElementById(id)?.classList.contains('section'))return false;
 const context={id,previousTab:STATE.tab};
 // Former nested wrappers performed their "before" work from outermost to innermost.
 const hooks=PS_NAV_HOOKS.slice();
 for(let i=hooks.length-1;i>=0;i--)if(hooks[i].before)hooks[i].before(context);
 STATE.tab=id;
 document.querySelectorAll('.section').forEach(e=>e.classList.toggle('active',e.id===id));
 document.querySelectorAll('.nav button[data-tab]').forEach(b=>{
  const active=b.dataset.tab===id;
  b.classList.toggle('active',active);
  if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');
 });
 if(id==='evidence')renderDocs();
 if(id==='interview')renderChat();
 if(id==='timeline'){renderEvents();tlRender();}
 if(id==='deduction')dedRender();
 if(id==='inspection12'){scMarkRoom();scRender();}
 if(id==='final')fcRender();
 if(id==='notebook')scRenderNotebook();
 if(id==='labs'){tcmsRefresh();msgRefresh();cctvRefresh();forensicRefresh();accessRefresh();}
 if(id==='labs'&&window.stage3)window.stage3.render();
 window.scrollTo({top:0,behavior:'instant'});
 // The same order as before: innermost wrapper finished before the outer wrappers.
 for(const hook of hooks)if(hook.after)hook.after(context);
}
function psBindNavigation(){
 document.querySelectorAll('[data-tab],[data-go]').forEach(button=>{
  button.addEventListener('click',()=>{
   if(button.disabled || button.getAttribute('aria-disabled')==='true')return;
   showTab(button.dataset.tab||button.dataset.go);
  });
 });
}
psBindNavigation();
window.PS_NAV=Object.freeze({open:showTab, tabs:PS_NAV_TABS, getActive:()=>STATE.tab,
 inspect:()=>({active:STATE.tab,modules:PS_NAV_TABS.slice(),hooks:PS_NAV_HOOKS.map(h=>h.name)})});
const catList=[...new Set(DOCS.map(x=>x.category))];
const EV_DOCS_IN_CATEGORY=Object.fromEntries(catList.map(cat=>[cat,DOCS.filter(d=>d.category===cat).map(d=>d.id)]));
$('filterCategory').innerHTML='<option value="">Wszystkie kategorie</option>'+catList.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');
let activeDoc=INITIAL[0];
const CAT_LABELS={
 'medyczno-sądowe':'Medycyna sądowa',
 'techniczno-taborowe':'Technika i tabor',
 'cyfrowe/komunikacyjne':'Dane i łączność',
 'wizualne/CCTV':'Nagrania i monitoring',
 'administracyjne/zeznania':'Dokumenty i zeznania',
 'laboratoryjne/mikroślady':'Ślady i analizy'
};
const CAT_MARKS={
 'medyczno-sądowe':'MED','techniczno-taborowe':'TEC',
 'cyfrowe/komunikacyjne':'DIG','wizualne/CCTV':'CCTV',
 'administracyjne/zeznania':'ADM','laboratoryjne/mikroślady':'LAB'
};
// Trzy semantyczne rodzaje dowodów w aktach. Kategorie techniczne pozostają niezależnymi teczkami.
const EVIDENCE_TYPES=Object.freeze({
 document:Object.freeze({label:'Dokumenty',shortLabel:'Dokument'}),
 testimony:Object.freeze({label:'Zeznania',shortLabel:'Zeznanie'}),
 trace:Object.freeze({label:'Ślady rzeczowe',shortLabel:'Ślad rzeczowy'})
});
const EVIDENCE_ICON_SVG=Object.freeze({
 document:'<path d="M8 3h7l5 5v13H8a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z"/><path d="M15 3v6h5M10 13h6M10 17h6"/>',
 testimony:'<path d="M20.5 11.5a7.5 7.5 0 0 1-7.5 7.5H8l-4 3v-6a7.5 7.5 0 1 1 16.5-4.5Z"/><path d="M8.5 10.5h7M8.5 14h5"/>',
 trace:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m15.9 15.9 5.1 5.1M8 11h5.8M10.9 8.1v5.8"/>',
 all:'<rect x="4" y="4" width="7" height="7" rx="1"/><rect x="13" y="4" width="7" height="7" rx="1"/><rect x="4" y="13" width="7" height="7" rx="1"/><rect x="13" y="13" width="7" height="7" rx="1"/>'
});
function renderEvidenceIcon(type){
 return `<svg class="ev-type-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${EVIDENCE_ICON_SVG[type]||EVIDENCE_ICON_SVG.document}</svg>`;
}
function getEvidenceType(material){
 const label=norm(material.title);
 // Dokumentacja administracyjna nie staje się zeznaniem tylko dlatego, że leży w teczce „zeznania”.
 if(/\b(zeznan|przesluchan|oswiadczen|relacj[aie])/.test(label))return 'testimony';
 // Mikroślady i ich analizy stanowią odrębną kategorię dowodów rzeczowych.
 if(material.category==='laboratoryjne/mikroślady')return 'trace';
 // Fotograficzne zabezpieczenia miejsca i rzeczy, a nie każdy plik wideo z CCTV.
 if(material.category==='wizualne/CCTV'&&material.acquisition==='oględziny'&&/\b(zdjecie|fotografi)/.test(label))return 'trace';
 return 'document';
}
let activeEvidenceType='all';
function evLabel(category){return CAT_LABELS[category]||category}
// Stable machine identifiers never appear as the primary label in the game.
const DOC_ORDER=Object.fromEntries(DOCS.map((d,i)=>[d.id,i+1]));
function evDisplayRef(d){return 'Materiał '+String(DOC_ORDER[d.id]||0).padStart(2,'0')}
function evDate(d){return d.document_time ? d.document_time.replace(/(\d{2}\.\d{2}) (\d{2}:\d{2})/,'$1.2026, $2') : 'Nie określono w źródle'}
function docName(id){return byId[id]?.title||String(id||'').replace(/_/g,' ').toLowerCase()}

function evSectionBody(body){
 return String(body||'').split(/\n\s*\n/).filter(x=>x.trim()).map((part,i)=>{
  let lines=part.trim().split('\n');
  let heading='';
  if(lines[0]===lines[0].toUpperCase() && lines[0].length<65){heading=lines.shift()}
  const content=lines.join('\n').trim();
  if(!content)return '';
  return `<section class="ev-text-section"><h4>${esc(heading||'Treść')}</h4><div class="ev-text-body">${esc(content).replace(/\n/g,'<br>')}</div></section>`
 }).join('');
}
function evDocMarkup(d, position, count){
 return `<div class="ev-sheet-content">
  <div class="ev-doc-topline"><span class="ev-doc-top-title">DOKUMENTACJA SPRAWY</span><span class="ev-doc-ref">${esc(evDisplayRef(d))}</span></div>
  <div class="ev-doc-classification"><span class="ev-type-icon ev-type-icon--${getEvidenceType(d)}">${renderEvidenceIcon(getEvidenceType(d))}</span><span>${esc(EVIDENCE_TYPES[getEvidenceType(d)].shortLabel)} · ${esc(evLabel(d.category))}</span></div>
  <h3 class="ev-doc-title">${esc(d.title)}</h3>
  <div class="ev-doc-details"><div><span>POCHODZENIE DOKUMENTU</span><strong>${esc(d.issuer||'Nie wskazano')}</strong></div>${d.document_time?`<div><span>CZAS ZAPISU</span><strong>${esc(evDate(d))}</strong></div>`:''}</div>
  <div class="ev-doc-body">${evSectionBody(d.body)}</div>
  <div class="ev-doc-bottom"><span>${esc(evDisplayRef(d))}</span><span>${esc(evLabel(d.category))}</span></div>
 </div>
 <nav class="ev-doc-nav" aria-label="Przeglądanie akt"><button type="button" data-ev-dir="-1" ${position===0?'disabled':''}>← Poprzedni</button><span>${position+1} / ${count}</span><button type="button" data-ev-dir="1" ${position===count-1?'disabled':''}>Następny →</button></nav>`;
}
// Indeks treści budowany tylko raz. Podczas wyszukiwania nie normalizujemy ponownie całych akt.
const EV_SEARCH_INDEX=Object.fromEntries(DOCS.map(d=>[d.id,norm([d.id,d.title,d.body,d.issuer,d.category].join(' '))]));
function evFilteredDocs(){
 const query=norm($('filterDocs').value), category=$('filterCategory').value;
 return DOCS.filter(d=>STATE.found.has(d.id)&&(!category||category===d.category)&&(activeEvidenceType==='all'||getEvidenceType(d)===activeEvidenceType)&&(!query||EV_SEARCH_INDEX[d.id].includes(query)));
}
function renderCounts(){
 const n=STATE.found.size;
 $('topCount')&&($('topCount').textContent=n+' z 78 materiałów');
 $('evCount').textContent=n+' / '+DOCS.length;
 const typeCounts={document:0,testimony:0,trace:0};
 for(const material of DOCS){if(STATE.found.has(material.id))typeCounts[getEvidenceType(material)]++;}
 $('evTypeFilters').innerHTML=[['all','Wszystkie',n],...Object.entries(EVIDENCE_TYPES).map(([type,definition])=>[type,definition.label,typeCounts[type]])]
  .map(([type,label,count])=>`<button type="button" class="ev-type-filter ${activeEvidenceType===type?'active':''}" data-evidence-type="${type}" aria-pressed="${activeEvidenceType===type}" aria-label="${esc(label)}, ${count} materiałów"><span class="ev-type-filter-icon ev-type-icon--${type}">${renderEvidenceIcon(type)}</span><span class="ev-type-filter-name">${esc(label)}</span><span class="ev-type-filter-count">${count}</span></button>`).join('');
 $('evTypeFilters').querySelectorAll('[data-evidence-type]').forEach(button=>button.addEventListener('click',()=>{
  activeEvidenceType=button.dataset.evidenceType;
  activeDoc='';
  $('evidence').classList.remove('ev-reading');
  renderDocs();
 }));
 const category=$('filterCategory').value;
 $('evDetailedCategoryLabel').textContent=category?'Teczka: '+evLabel(category):'Szczegółowe teczki (6)';
 const all=STATE.found.size;
 $('categoryCount').innerHTML=`<button type="button" class="ev-folder ${!category?'active':''}" data-ev-category="" aria-pressed="${!category}"><span class="ev-folder-marker">✦</span><span>Wszystkie akta</span><b>${all}</b></button>`+
 catList.map((cat)=>{
  const count=EV_DOCS_IN_CATEGORY[cat].reduce((n,id)=>n+Number(STATE.found.has(id)),0);
  return `<button type="button" class="ev-folder ${category===cat?'active':''}" data-ev-category="${esc(cat)}" aria-pressed="${category===cat}"><span class="ev-folder-marker">${esc(CAT_MARKS[cat]||'AKT')}</span><span>${esc(evLabel(cat))}</span><b>${count}</b></button>`;
 }).join('');
 $('categoryCount').querySelectorAll('[data-ev-category]').forEach(b=>b.addEventListener('click',()=>{
  $('filterCategory').value=b.dataset.evCategory;
  activeDoc='';
  $('evidence').classList.remove('ev-reading');
  renderDocs();
 }));
}
function renderDocs(){
 renderCounts();
 const found=evFilteredDocs();
 $('evResultCount').textContent=String(found.length).padStart(2,'0');
 if(!found.some(d=>d.id===activeDoc))activeDoc=found[0]?.id||'';
 $('docList').innerHTML=found.length?found.map((d,i)=>`
  <button type="button" class="ev-file ${activeDoc===d.id?'selected':''}" data-doc="${esc(d.id)}" aria-current="${activeDoc===d.id?'true':'false'}">
   <span class="ev-file-n">${String(i+1).padStart(2,'0')}</span>
   <span class="ev-type-icon ev-type-icon--${getEvidenceType(d)}" aria-label="${esc(EVIDENCE_TYPES[getEvidenceType(d)].shortLabel)}" role="img">${renderEvidenceIcon(getEvidenceType(d))}</span>
   <span class="ev-file-main"><span class="ev-file-class">${esc(evLabel(d.category))}<span class="ev-file-type-text">${esc(EVIDENCE_TYPES[getEvidenceType(d)].shortLabel)}</span></span><strong>${esc(d.title)}</strong><small>${esc(d.issuer||'Źródło niepodane')}</small></span>
   <span class="ev-file-arrow" aria-hidden="true">↗</span>
  </button>`).join(''):'<div class="ev-no-results"><span>◇</span><strong>Brak dokumentów</strong><p>Zmień kategorię lub wyszukiwane słowa.</p></div>';
 if(activeDoc&&STATE.found.has(activeDoc)){
   const index=found.findIndex(d=>d.id===activeDoc);
   $('docPaper').innerHTML=evDocMarkup(byId[activeDoc],index,found.length);
 }else{
   $('docPaper').innerHTML='<div class="ev-empty"><span class="ev-empty-signet">◇</span><h3>Nie ma dokumentu do wyświetlenia</h3><p>Zmień filtry, aby przejrzeć zgromadzone materiały.</p></div>';
 }
}
// Jeden słuchacz działa również po zmianie filtrów i przebudowaniu listy.
$('docList').addEventListener('click',event=>{
 const b=event.target.closest('[data-doc]');
 if(!b||!$('docList').contains(b))return;
 activeDoc=b.dataset.doc;if(STATE.found.has(activeDoc))STATE.reviewedEvidence.add(activeDoc);renderDocs();renderAttached();$('evidence').classList.add('ev-reading');
 if(window.innerWidth<=850)$('docPaper').scrollIntoView({behavior:'smooth',block:'start'});
});
$('docPaper').addEventListener('click',(event)=>{
 const button=event.target.closest('[data-ev-dir]');if(!button)return;
 const found=evFilteredDocs(), index=found.findIndex(d=>d.id===activeDoc), next=found[index+Number(button.dataset.evDir)];
 if(next){activeDoc=next.id;if(STATE.found.has(activeDoc))STATE.reviewedEvidence.add(activeDoc);renderDocs();renderAttached();if(window.innerWidth<=850)$('docPaper').scrollIntoView({behavior:'smooth',block:'start'});}
});
$('evBack').addEventListener('click',()=>{$('evidence').classList.remove('ev-reading');$('docList').scrollIntoView({behavior:'smooth',block:'start'});});
$('evClear').addEventListener('click',()=>{$('filterDocs').value='';$('filterCategory').value='';activeEvidenceType='all';$('evidence').classList.remove('ev-reading');activeDoc='';renderDocs();});

{let evT=null;$('filterDocs').addEventListener('input',()=>{clearTimeout(evT);evT=setTimeout(renderDocs,120);});}$('filterCategory').addEventListener('change',renderDocs);
function renderAreas(){$('areas').innerHTML=AREAS.map(a=>`<button class="location ${a.id===STATE.area?'selected':''}" data-area="${a.id}"><b>${esc(a.title)}</b><span>${esc(a.desc)}</span></button>`).join('');$('areas').querySelectorAll('[data-area]').forEach(b=>b.addEventListener('click',()=>{STATE.area=b.dataset.area;renderAreas();$('searchResults').textContent='Wpisz, czego szukasz w tym obszarze.';}));}
const PS_GENERIC=new Set(['karta','raport','rejest','zapis','protok','dokume','lista','wydruk','zglosz','polece','system','wiadom','serwis']);
function scoreDoc(q,d){const qt=tokens(q).filter(t=>!PS_GENERIC.has(t)),dt=tokens(d.title+' '+d.id);if(!qt.length)return 0;let m=0;for(const t of qt){if(dt.some(x=>x.startsWith(t)||t.startsWith(x)))m++;}let score=m/qt.length;if(qt.length>1&&m<2)score*=.5;if(norm(d.title).includes(norm(q))&&norm(q).length>5)score+=1;return score;}
function searchArea(){const q=$('searchQuery').value.trim(),box=$('searchResults');if(q.length<4){box.textContent='Wpisz bardziej konkretny przedmiot poszukiwań.';return;}if(!tokens(q).some(t=>!PS_GENERIC.has(t))){box.textContent='To zbyt ogólne określenie. Nazwij konkretny przedmiot, system, osobę lub miejsce.';return;}
const possible=DOCS.filter(d=>d.area===STATE.area&&searchCanAcquire(d)&&!STATE.found.has(d.id)&&!sceneDocBlocked(d.id)).map(d=>({d,sc:scoreDoc(q,d)})).filter(x=>x.sc>=.43).sort((a,b)=>b.sc-a.sc);
if(!possible.length){const locked=DOCS.filter(d=>d.area===STATE.area&&searchCanAcquire(d)&&!STATE.found.has(d.id)&&sceneDocBlocked(d.id)).map(d=>({d,sc:scoreDoc(q,d)})).filter(x=>x.sc>=.43).sort((a,b)=>b.sc-a.sc);if(locked.length){box.textContent='Najpierw zdobądź wcześniejsze ustalenia: '+scDocMissing(locked[0].d.id).map(id=>byId[id]?.title||id).join('; ')+'. Możesz je zbadać również podczas oględzin zajezdni.';return;}box.textContent='Nie odnaleziono nowego materiału spełniającego to kryterium w wybranym obszarze. Możesz sprawdzić inne źródło lub użyć precyzyjniejszego określenia.';return;}
const pick=possible[0].d;STATE.found.add(pick.id);PS_EVENTS.evidence(pick.id,'area-search');activeDoc=pick.id;box.innerHTML=`<b style="color:var(--green)">Zabezpieczono materiał:</b> ${esc(pick.title)} <span class="muted small">(${esc(evDisplayRef(pick))})</span> <button class="btn alt" id="openAcquired" style="margin-left:9px">Odczytaj</button>`;$('openAcquired').addEventListener('click',()=>showTab('evidence'));renderCounts();renderAttached();tcmsRefresh();msgRefresh();cctvRefresh();forensicRefresh();accessRefresh();toast('Do akt dodano: '+pick.title);}
$('searchBtn').addEventListener('click',searchArea);$('searchQuery').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchArea();}});

const NPC8_PORTRAITS={
 MAREK:{skin:'#c99e80',light:'#e4bda0',shade:'#9b6d58',hair:'#3e3d38',hairLight:'#777366',cloth:'#303e48',clothLight:'#566269',accent:'#c4a16b',bg1:'#435052',bg2:'#19272b',eye:'#748b87',hairStyle:'side-part',outfit:'jacket',beard:'stubble',lines:true},
 TOMASZ:{skin:'#bd9072',light:'#dcaf8e',shade:'#885e4a',hair:'#292b2a',hairLight:'#58574c',cloth:'#3b5365',clothLight:'#708494',accent:'#ac8869',bg1:'#394d56',bg2:'#14272f',eye:'#7a8277',hairStyle:'short',outfit:'uniform',beard:'stubble'},
 JANUSZ:{skin:'#c39a7a',light:'#e1b798',shade:'#936b52',hair:'#635e4f',hairLight:'#ada38c',cloth:'#695443',clothLight:'#978068',accent:'#c1a06a',bg1:'#514c3f',bg2:'#292923',eye:'#7f8272',hairStyle:'wave',outfit:'work',beard:'full',lines:true},
 ELZBIETA:{skin:'#d3ab90',light:'#edcbb1',shade:'#a27a64',hair:'#754d37',hairLight:'#b68b61',cloth:'#475b59',clothLight:'#788882',accent:'#c8ab75',bg1:'#4e5952',bg2:'#24322f',eye:'#7d8b76',hairStyle:'bob',outfit:'cardigan',lines:true},
 KAMIL:{skin:'#cda487',light:'#e9c3a5',shade:'#a1755c',hair:'#303230',hairLight:'#65695f',cloth:'#314c52',clothLight:'#577378',accent:'#a8c5bb',bg1:'#3b5357',bg2:'#1a3035',eye:'#778d8c',hairStyle:'quiff',outfit:'zip',glasses:true},
 MAGDALENA:{skin:'#d0a58b',light:'#ebc4a8',shade:'#9f735f',hair:'#44332d',hairLight:'#88664e',cloth:'#41464d',clothLight:'#727479',accent:'#c8aa7c',bg1:'#534d50',bg2:'#2d292f',eye:'#847865',hairStyle:'bun',outfit:'blazer'}
};
function npc8Initials(name){return String(name||'').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('');}
function npc8GetState(c){
 const fallback={rapport:34,tension:28,fatigue:12,stance:'neutral',mood:'rzeczowy'};
 let st=fallback;
 try{if(typeof NPC4_STATE!=='undefined'&&NPC4_STATE&&NPC4_STATE[c.id])st=NPC4_STATE[c.id];}catch(err){}
 const rapport=Math.round(Math.max(0,Math.min(100,st.rapport??fallback.rapport)));
 const tension=Math.round(Math.max(0,Math.min(100,st.tension??fallback.tension)));
 const fatigue=Math.round(Math.max(0,Math.min(100,st.fatigue??fallback.fatigue)));
 const f=c.gender==='f';let mood=f?'rzeczowa':'rzeczowy',cls='is-neutral';
 if(fatigue>=68){mood=f?'zmęczona':'zmęczony';cls='is-tired';}
 else if(tension>=76){mood=f?'spięta':'spięty';cls='is-tense';}
 else if((st.stance==='firm'&&tension>=58)||tension>=60){mood='na dystans';cls='is-guarded';}
 else if(rapport>=58&&tension<55){mood=f?'bardziej otwarta':'bardziej otwarty';cls='is-open';}
 const last=(STATE.dialogues[c.id]||[]).slice(-1)[0];
 return {rapport,tension,fatigue,mood,cls,speaking:last&&last.role==='npc'?'is-speaking':'',stance:st.stance||'neutral'};
}
// Każdy portret otrzymuje własne identyfikatory gradientów i masek SVG.
