function npc91Clean(s){return norm(s).replace(/\b(?:no dobra|sluchaj|sluchaj no|powiedz mi|powiedzze|tak szczerze|szczerze mowiac|bez kitu|bez sciemy|wez mi powiedz|stary|ej|kurde|pytam serio|po ludzku|wiesz co)\b[ ,.:;!?-]*/g,' ').replace(/\s+/g,' ').trim();}
