function safeLoad(d){const snap=JSON.parse(JSON.stringify(buildSave()));try{applySave(d);}catch(err){try{applySave(snap);}catch(_){}throw err;}}
function exportSave(){const save=buildSave();const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Ostatni_kurs_zapis_sprawy.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),12000);toast('Zapis sprawy został pobrany.');}
$('saveBtn').addEventListener('click',exportSave);$('loadBtn').addEventListener('click',()=>$('loadFile').click());
$('loadFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>25*1024*1024)throw Error('Plik zapisu przekracza limit 25 MB.');const d=JSON.parse(await f.text());safeLoad(d);psSessionActive=true;document.getElementById('psResumeOffer')?.remove();toast('Wczytano zapis sprawy.');}catch(err){toast('Nie udało się odczytać zapisu: '+err.message);}e.target.value='';});
$('resetBtn').addEventListener('click',()=>psAsk('Wyczyścić całą aktualną sesję bez możliwości przywrócenia (jeśli nie zapisano jej ręcznie)?',()=>{STATE.found=new Set(INITIAL);STATE.reviewedEvidence.clear();STATE.notes='';STATE.events=[];simReset();tcmsReset();msgReset();cctvReset();forensicReset();accessReset();dedReset();tlReset();scReset();fcReset();for(const c of CONTENT.characters)STATE.dialogues[c.id]=[{role:'npc',text:c.voice.opening}];npc9Reset();npc4Reset();$('notes').value='';$('filterDocs').value='';$('filterCategory').value='';activeDoc=INITIAL[0];renderDocs();renderEvents();tlRender();renderChat();dedRender();scRender();scRenderNotebook();fcRender();showTab('overview');STATE.activeChar=CONTENT.characters[0].id;['searchQuery','filterDocs'].forEach(id=>{const el=$(id);if(el)el.value='';});if($('searchResults'))$('searchResults').textContent='';renderChat();renderDocs();tcmsRefresh();msgRefresh();cctvRefresh();forensicRefresh();accessRefresh();ui14Update();window.PS_MG2_QA?.reset?.();window.PS_MG3_QA?.reset?.();psClearSave();window.PS617_SYNC?.resetSession?.();psReset();PS_EVENTS.resetSession();if(window.stage3)window.stage3.reset();toast('Nowa sesja: wyzerowano postęp.');}));
