const FORENSIC_KEY={"count":185,"inputs":["ADM-14","LAB-01","LAB-02","LAB-03","LAB-04","LAB-05","LAB-06","LAB-07"],"outputs":["MED-09","MED-10","LAB-08","LAB-09","LAB-10","MED-04","MED-05","MED-06"],"essential_pairs":[["W-7A","P-A1"],["W-7A","C-0W"],["S-3A","S-W1"],["K-N1","K-R2"],["K-N1","K-R1"],["U-P1","U-F0"],["U-P2","U-F0"]],"required_risk_check":["S-3A","C-RĘ"]};
const FO_BYID=Object.fromEntries(FORENSIC_SAMPLES.map(x=>[x.id,x]));
const FO_INPUT=FORENSIC_KEY.inputs,FO_OUTPUT=FORENSIC_KEY.outputs;
function forensicDefault(){return {filters:{kind:'',query:'',risk:''},page:0,selected:'',left:'',right:'',comparisons:[],interpretation:{fiber:'',grease:'',contact:'',injury:'',contamination:'',identity:'',source:'',notes:''},attempts:0,solved:false};}
function forensicExport(){const x=STATE.forensic;return {filters:x.filters,page:x.page,selected:x.selected,left:x.left,right:x.right,comparisons:x.comparisons.map(v=>[v[0],v[1]]),interpretation:x.interpretation,attempts:x.attempts};}
function forensicAvailable(){return FO_INPUT.filter(id=>STATE.found.has(id)).length>=2;}
function forensicPairKey(a,b){return [a,b].sort().join('|');}
function forensicDistance(a,b){const x=FO_BYID[a],y=FO_BYID[b];if(!x||!y||x.kind!==y.kind)return null;const delta=x.vector.reduce((s,v,i)=>s+Math.abs(v-y.vector[i]),0)/6;return Math.round(delta*10)/10;}
function forensicPairState(a,b){const d=forensicDistance(a,b);if(d===null)return 'Nieporównywalne rodzaje materiału';return d<=7?'zgodność klasy':d<=17?'wynik niejednoznaczny':'brak zgodności';}
function forensicCheck(st,found){if(!st||!FO_INPUT.every(id=>found.has(id)))return false;
 const pairset=new Set((st.comparisons||[]).filter(p=>Array.isArray(p)&&p.length===2&&FO_BYID[p[0]]&&FO_BYID[p[1]]).map(p=>forensicPairKey(p[0],p[1])));
 if(!FORENSIC_KEY.essential_pairs.every(p=>pairset.has(forensicPairKey(...p))))return false;
 if(!pairset.has(forensicPairKey(...FORENSIC_KEY.required_risk_check)))return false;
 const v=st.interpretation||{};
 if(v.fiber!=='zgodnosc_nie_identyfikacja'||v.grease!=='pospolity_material'||v.contact!=='zgodnosc_nie_jedyny'||v.injury!=='dwa_mechanizmy'||v.contamination!=='transfer_wtorny'||v.identity!=='brak_identyfikacji'||v.source!=='LAB-06')return false;
 const note=String(v.notes||'').trim();if(note.startsWith('m5:'))return mini5Correct('forensic',note);if(note.length<110)return false;
 // Report must cite both an evidence-bound limitation and an independent modality.
 if(!/w.l.kn|smar|materia|slad/i.test(note))return false;
 return true;
}
function forensicFiltered(){const f=STATE.forensic.filters,q=norm(f.query);return FORENSIC_SAMPLES.filter(x=>(!f.kind||x.kind===f.kind)&&(!f.risk||x.risk===f.risk)&&(!q||norm(x.id+' '+x.origin+' '+x.description+' '+x.marker).includes(q)));}
function forensicRefresh(){tcmsCards();if($('forensicPanel')&&!$('forensicPanel').hidden)forensicRender();}
function forensicRender(){const root=$('forensicWorkspace');if(!root)return;const st=STATE.forensic;
 const pills=FO_INPUT.map(id=>`<span class="fo-badge ${STATE.found.has(id)?'have':''}">${esc(docName(id))} · ${STATE.found.has(id)?'uzyskano':'do odnalezienia'}</span>`).join('');
 if(!forensicAvailable()){root.innerHTML=`<div class="surface padded"><div class="eyebrow">BADANIE ŚLADÓW</div><h2 style="margin-top:10px">Analiza kryminalistyczna</h2><p>Najpierw odnajdź co najmniej dwa dokumenty dotyczące pobierania i porównywania śladów w aktach sprawy. Pełny raport wymaga kompletu materiałów wejściowych.</p><div class="fo-badges">${pills}</div></div>`;return;}
 root.innerHTML=`<div class="fo-shell"><div class="surface padded"><div class="fo-head"><div><div class="eyebrow">LABORATORIUM MATERIAŁOWE</div><h2 style="margin:8px 0">Laboratorium kryminalistyczne</h2><p class="muted small">Dopasowanie klasy materiału nie oznacza identyfikacji osoby. Ustal, które ślady są znaczące, a które mogą być efektem pracy hali lub transferu wtórnego.</p></div><span class="chip">${FORENSIC_SAMPLES.length} próbek</span></div><div class="fo-badges">${pills}</div></div>
 <div class="fo-grid"><section class="surface padded"><div class="eyebrow">REJESTR BADANYCH PRÓBEK</div><div class="fo-filters"><label>Rodzaj<select id="foKind"><option value="">Wszystkie</option>${['WŁÓKNO','SMAR','KONTAKT','URAZ','KONTROLA'].map(v=>`<option value="${v}" ${st.filters.kind===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Ryzyko transferu<select id="foRisk"><option value="">Dowolne</option>${['niskie','średnie','wysokie'].map(v=>`<option ${st.filters.risk===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Szukaj po nazwie, źródle lub numerze<input id="foQuery" value="${esc(st.filters.query)}" placeholder="np. materiał, C0, osłona..."></label></div><div class="fo-tablewrap"><table class="fo-table"><thead><tr><th>Próbka</th><th>Rodzaj</th><th>Pochodzenie</th><th>Status</th></tr></thead><tbody id="foRows"></tbody></table></div><div class="fo-page"><button id="foPrev">Wstecz</button><span id="foCount" class="muted small">—</span><button id="foNext">Dalej</button></div></section>
 <section class="surface padded"><div class="eyebrow">INSPEKTOR PRÓBKI</div><div id="foSample" class="fo-sample">Wybierz próbkę z rejestru.</div><div id="foSpectrum" class="fo-spectrum" aria-label="Sześć umownych cech porównawczych"></div><p class="muted tiny">Wykres zestawia umowne profile próbek. Podobieństwo cech nie oznacza jeszcze wspólnego pochodzenia.</p></section></div>
 <section class="surface padded"><div class="eyebrow">STANOWISKO PORÓWNAWCZE</div><h3 style="margin:9px 0">Porównaj dwa źródła i zachowaj wynik</h3><p class="fo-report-help">Badanie wymaga rozważenia materiałów z miejsca zdarzenia, wzorców kontrolnych, zwykłych śladów warsztatowych i grup obrażeń. Porównania różnych rodzajów próbek nie mają sensu.</p><div class="fo-compare"><label>Próbka A<select id="foLeft"><option value="">Wybierz próbkę...</option>${FORENSIC_SAMPLES.map(x=>`<option value="${esc(x.id)}" ${st.left===x.id?'selected':''}>${esc(x.id)} · ${esc(x.origin)}</option>`).join('')}</select></label><label>Próbka B<select id="foRight"><option value="">Wybierz próbkę...</option>${FORENSIC_SAMPLES.map(x=>`<option value="${esc(x.id)}" ${st.right===x.id?'selected':''}>${esc(x.id)} · ${esc(x.origin)}</option>`).join('')}</select></label><button class="btn" id="foCompare">Zbadaj</button></div><div class="fo-comparison" id="foCurrent">Wybierz parę próbek do porównania.</div><div class="eyebrow">DZIENNIK PORÓWNAŃ</div><div class="fo-journal" id="foJournal"></div></section>
 <section class="surface padded"><div class="eyebrow">OCENA ŚLADÓW / RAPORT</div><h3 style="margin:9px 0">Wnioski pod rygorem ograniczeń dowodowych</h3><p class="fo-report-help">Nie opieraj się na samym podobieństwie. Oceń, czego dane nie dowodzą. Dokumenty końcowe można uzyskać dopiero po wykonaniu serii porównań i uzasadnieniu wniosków.</p><div class="fo-report">${forensicSelect('fiber','Włókna W-7 i próbka wyposażenia',[['unikatowa_id','Unikatowo identyfikują właściciela'],['zgodnosc_nie_identyfikacja','Zgodna klasa, bez identyfikacji osoby'],['brak_zgodnosci','Nie stwierdzono zgodności']])}${forensicSelect('grease','Smar S-3',[['pospolity_material','Szeroko rozpowszechniony materiał warsztatowy'],['jedna_osoba','Ślad identyfikuje pracownika'],['wynik_ujemny','Nie wykryto smaru']])}${forensicSelect('contact','Ślad K1 i wzorce kontaktu',[['zgodnosc_nie_jedyny','Zgodność cech, nie jedyny możliwy przedmiot'],['pewny_przedmiot','Pewna identyfikacja narzędzia'],['brak_kontaktu','Brak śladu kontaktowego']])}${forensicSelect('injury','Dwie grupy urazów',[['jeden_upadek','Wszystkie obrażenia wynikają z jednego upadku'],['dwa_mechanizmy','Wymagają rozważenia dwóch mechanizmów kontaktu'],['toksykologia','Wyłącznie zatrucie']])}${forensicSelect('contamination','Skażenie wtórne',[['nie_ma','Wykluczone we wszystkich próbkach'],['transfer_wtorny','Możliwe w części próbek; sprawdzić kontrole'],['wszystkie_skazone','Wszystkie próbki są niewiarygodne']])}${forensicSelect('identity','Granica identyfikacji',[['brak_identyfikacji','Ślady nie identyfikują sprawcy'],['identyfikacja','Można wskazać jednoznacznie osobę'],['na_podstawie_tc','Wystarcza zgodność smaru']])}<label>Dokument kontroli niezależnej<select id="foSource"><option value="">Wybierz zdobyte źródło...</option>${DOCS.filter(x=>STATE.found.has(x.id)).map(x=>`<option value="${esc(x.id)}">${esc(x.id)} — ${esc(x.title)}</option>`).join('')}</select></label><div class="wide">${mini5Select('forensic','foNotes',st.interpretation.notes||'')}</div></div><div class="fo-footer"><button class="btn" id="foSubmit" ${st.solved?'disabled':''}>Zatwierdź opinię porównawczą</button><span class="muted small">Próby: <b id="foAttempts">${st.attempts}</b></span></div><div id="foFeedback" class="fo-feedback">${st.solved?'Raport zweryfikowany. Pięć opracowań dołączono do akt. Analiza nie ustala tożsamości sprawcy.':'Wykonaj porównania, oceń skażenie i uzasadnij zakres ustaleń. Błędna hipoteza nie niszczy próbek.'}</div></section></div>`;
 for(const [id,key] of [['foKind','kind'],['foRisk','risk'],['foQuery','query']])$(id).addEventListener('input',()=>{st.filters[key]=$(id).value;st.page=0;forensicRenderRows();});
 $('foPrev').addEventListener('click',()=>{st.page=Math.max(0,st.page-1);forensicRenderRows();});$('foNext').addEventListener('click',()=>{st.page++;forensicRenderRows();});
 $('foLeft').addEventListener('change',e=>st.left=e.target.value);$('foRight').addEventListener('change',e=>st.right=e.target.value);
 $('foCompare').addEventListener('click',forensicCompare);
 for(const key of ['fiber','grease','contact','injury','contamination','identity']){const el=$('fo_'+key);el.value=st.interpretation[key];el.addEventListener('change',e=>st.interpretation[key]=e.target.value);}
 $('foSource').value=st.interpretation.source;$('foSource').addEventListener('change',e=>st.interpretation.source=e.target.value);
 $('foNotes').value=st.interpretation.notes;$('foNotes').addEventListener('input',e=>st.interpretation.notes=e.target.value.slice(0,4000));$('foSubmit').addEventListener('click',forensicSubmit);
 forensicRenderRows();forensicRenderSample();forensicRenderJournal();}
function forensicSelect(key,title,options){return `<label>${esc(title)}<select id="fo_${key}"><option value="">Wybierz ocenę...</option>${options.map(([id,v])=>`<option value="${esc(id)}">${esc(v)}</option>`).join('')}</select></label>`;}
function forensicRenderRows(){const st=STATE.forensic,list=forensicFiltered(),pages=Math.max(1,Math.ceil(list.length/35));st.page=Math.min(st.page,pages-1);const rows=list.slice(st.page*35,(st.page+1)*35);
 $('foRows').innerHTML=rows.map(x=>`<tr data-fo-sample="${esc(x.id)}" class="${st.selected===x.id?'fo-selected':''}"><td><b>${esc(x.id)}</b></td><td>${esc(x.kind)}</td><td>${esc(x.origin)}</td><td>${esc(x.flag)}<small>${esc(x.risk)} ryzyko</small></td></tr>`).join('');$('foCount').textContent=`${list.length} z ${FORENSIC_SAMPLES.length} · strona ${st.page+1}/${pages}`;$('foPrev').disabled=st.page===0;$('foNext').disabled=st.page>=pages-1;
 $('foRows').querySelectorAll('[data-fo-sample]').forEach(row=>row.addEventListener('click',()=>{st.selected=row.dataset.foSample;forensicRenderRows();forensicRenderSample();}));}
function forensicRenderSample(){const x=FO_BYID[STATE.forensic.selected];$('foSample').textContent=x?`${x.id} · ${x.kind}\n${x.origin}\n${x.description}\nPochodzenie: ${x.flag}; plomba: ${x.seal}\nRyzyko transferu: ${x.risk}\nOznaczenie porównawcze: ${x.marker}`:'Wybierz próbkę z rejestru.';$('foSpectrum').innerHTML=x?x.vector.map((v,i)=>`<i style="height:${v}%" title="Cecha ${i+1}: ${v}"></i>`).join(''):'';}
function forensicCompare(){const st=STATE.forensic,a=st.left,b=st.right;if(!a||!b||a===b||!FO_BYID[a]||!FO_BYID[b]){$('foCurrent').textContent='Wybierz dwie różne próbki.';return;}
 const x=FO_BYID[a],y=FO_BYID[b],distance=forensicDistance(a,b),kind=forensicPairState(a,b);
 if(distance===null){$('foCurrent').textContent='Nie wolno porównywać w jednej skali różnych klas materiału. Wybierz próbki tego samego rodzaju.';return;}
 $('foCurrent').textContent=`${a} ↔ ${b}\nWynik: ${kind}. Średnia różnica cech: ${distance} jednostek umownych.\nŹródła: ${x.origin} / ${y.origin}.\nUwaga: nawet duża zgodność cech nie ustala tożsamości osoby ani czasu transferu.`;
 const key=forensicPairKey(a,b);if(!st.comparisons.some(p=>forensicPairKey(...p)===key))st.comparisons.push([a,b]);forensicRenderJournal();}
function forensicRenderJournal(){const st=STATE.forensic;$('foJournal').innerHTML=st.comparisons.length?st.comparisons.map(p=>`<div><b>${esc(p[0])} ↔ ${esc(p[1])}</b> · ${esc(forensicPairState(...p))}; ryzyko transferu należy ocenić osobno.</div>`).join(''):'<div>Nie przeprowadzono jeszcze żadnego porównania.</div>';}
function forensicSubmit(){const st=STATE.forensic;st.attempts++;$('foAttempts').textContent=st.attempts;
 if(forensicCheck(st,STATE.found)){st.solved=true;for(const id of FO_OUTPUT)STATE.found.add(id);PS_EVENTS.laboratory('forensic',FO_OUTPUT);renderDocs();renderAttached();toast('Zatwierdzono opinię laboratoryjną. Dołączono '+FO_OUTPUT.length+' materiałów do akt.');forensicRefresh();return;}
 const errors=[];if(!FO_INPUT.every(x=>STATE.found.has(x)))errors.push('Raport wymaga wszystkich ośmiu dokumentów źródłowych.');if(st.comparisons.length<8)errors.push('Przeprowadzono zbyt mało odrębnych porównań, w tym prób kontrolnych.');if(Object.values(st.interpretation).filter(Boolean).length<8)errors.push('Opinia zawiera nieuzupełnione pola lub nie ma uzasadnienia.');if(!errors.length)errors.push('Nie potwierdzono doboru porównań lub zgodności interpretacji z danymi. Sprawdź próbki kontrolne, rozróżnienie dwóch grup urazów oraz granice identyfikacji.');$('foFeedback').textContent=errors.join('\n');}
function forensicRestore(saved){const st=forensicDefault();if(saved&&typeof saved==='object'){
 if(saved.filters&&typeof saved.filters==='object')for(const k of Object.keys(st.filters))if(typeof saved.filters[k]==='string')st.filters[k]=saved.filters[k].slice(0,100);
 if(Number.isInteger(saved.page)&&saved.page>=0&&saved.page<100)st.page=saved.page;
 for(const k of ['selected','left','right'])if(typeof saved[k]==='string'&&FO_BYID[saved[k]])st[k]=saved[k];
 if(Array.isArray(saved.comparisons))st.comparisons=saved.comparisons.filter(p=>Array.isArray(p)&&p.length===2&&FO_BYID[p[0]]&&FO_BYID[p[1]]&&p[0]!==p[1]&&forensicDistance(...p)!==null).slice(0,200);
 if(saved.interpretation&&typeof saved.interpretation==='object')for(const k of Object.keys(st.interpretation))if(typeof saved.interpretation[k]==='string')st.interpretation[k]=saved.interpretation[k].slice(0,k==='notes'?4000:100);
 if(Number.isInteger(saved.attempts))st.attempts=Math.max(0,Math.min(10000,saved.attempts));
 st.solved=forensicCheck(st,STATE.found);if(st.solved)for(const id of FO_OUTPUT)STATE.found.add(id);
 }STATE.forensic=st;}
function forensicReset(){STATE.forensic=forensicDefault();for(const id of FO_OUTPUT)STATE.found.delete(id);if($('forensicWorkspace')&&!$('forensicPanel').hidden)forensicRender();}


